// Converte audio_base64 do body em binary pro node OpenAI Whisper
const body = $json.body || {};
const rawB64 = body.audio_base64 || '';
if (!rawB64) throw new Error('audio_base64 vazio');
const match = String(rawB64).match(/^data:([^;]+);base64,(.*)$/);
const mimeType = body.mime_type || (match ? match[1] : 'audio/ogg');
const clean = match ? match[2] : String(rawB64);
const buffer = Buffer.from(clean, 'base64');
const mt = mimeType.toLowerCase();
let ext = 'ogg';
if (mt.includes('mp4') || mt.includes('m4a')) ext = 'm4a';
else if (mt.includes('mpeg') || mt.includes('mp3')) ext = 'mp3';
else if (mt.includes('wav')) ext = 'wav';
else if (mt.includes('webm')) ext = 'webm';
const binaryData = await this.helpers.prepareBinaryData(buffer, `audio.${ext}`, mimeType);
return [{ json: { body }, binary: { data: binaryData } }];

// Converte binary "data" (mp3 do TTS) em base64 pro Respond
const bin = $binary && $binary.data;
if (!bin) throw new Error("TTS sem binary data");
const buffer = await this.helpers.getBinaryDataBuffer(0, "data");
const audio_base64 = buffer.toString("base64");
const mime = bin.mimeType || "audio/mpeg";
const output = $("IA Atendimento").item.json.output || "";
return [{ json: { output, audio_base64, mime } }];
